#include <stdio.h>
#include <stdlib.h>

#define MAXN 200005

static int N;
static long long bitA[MAXN + 1]; /* soma dos 'alpha': FRENTE (i+V), TRAS (V-i) */
static long long bitB[MAXN + 1]; /* soma dos coeficientes de x: FRENTE -1, TRAS +1 */

/* Atualiza prefixos (range add via diferenca, point query via prefixo) */
static inline void bitupd(long long *b, int pos, long long v) {
    for (; pos <= N; pos += pos & (-pos)) b[pos] += v;
}

static inline long long bitqry(const long long *b, int pos) {
    long long s = 0;
    for (; pos > 0; pos -= pos & (-pos)) s += b[pos];
    return s;
}

static char *rp;

static inline int rdint(void) {
    while (*rp && (*rp < '0' || *rp > '9')) rp++;
    int x = 0;
    while (*rp >= '0' && *rp <= '9') {
        x = x * 10 + (*rp - '0');
        rp++;
    }
    return x;
}

int main(void) {
    /* le toda a entrada de uma vez */
    size_t cap = 1u << 22;
    char *ibuf = (char *)malloc(cap);
    size_t ilen = 0;
    for (;;) {
        if (ilen + 1 >= cap) {
            cap <<= 1;
            ibuf = (char *)realloc(ibuf, cap);
        }
        size_t got = fread(ibuf + ilen, 1, cap - ilen - 1, stdin);
        if (got == 0) break;
        ilen += got;
    }
    ibuf[ilen] = '\0';
    rp = ibuf;

    N = rdint();
    int M = rdint();

    char *obuf = (char *)malloc((size_t)(M + 2) * 14 + 16);
    size_t op = 0;

    for (int q = 0; q < M; q++) {
        int type = rdint();
        if (type == 1) {
            /* FRENTE i V : posicoes i..min(N,i+V-1) recebem (V+i)-x */
            int i = rdint();
            int V = rdint();
            long long re = (long long)i + V - 1;
            int r = (re > (long long)N) ? N : (int)re;
            long long alpha = (long long)V + i;
            bitupd(bitA, i, alpha);
            bitupd(bitB, i, -1);
            if (r < N) {
                bitupd(bitA, r + 1, -alpha);
                bitupd(bitB, r + 1, 1);
            }
        } else if (type == 2) {
            /* TRAS i V : posicoes max(1,i-V+1)..i recebem x+(V-i) */
            int i = rdint();
            int V = rdint();
            long long lb = (long long)i - V + 1;
            int l = (lb < 1) ? 1 : (int)lb;
            long long alpha = (long long)V - i;
            bitupd(bitA, l, alpha);
            bitupd(bitB, l, 1);
            if (i < N) {
                bitupd(bitA, i + 1, -alpha);
                bitupd(bitB, i + 1, -1);
            }
        } else {
            /* IMPRIME x : soma das progressoes cobrindo x = alpha + x*slope */
            int x = rdint();
            long long ans = bitqry(bitA, x) + (long long)x * bitqry(bitB, x);
            if (ans == 0) {
                obuf[op++] = '0';
            } else {
                char tmp[24];
                int t = 0;
                long long v = ans;
                if (v < 0) { obuf[op++] = '-'; v = -v; }
                while (v > 0) { tmp[t++] = (char)('0' + (int)(v % 10)); v /= 10; }
                while (t > 0) obuf[op++] = tmp[--t];
            }
            obuf[op++] = '\n';
        }
    }

    fwrite(obuf, 1, op, stdout);
    free(ibuf);
    free(obuf);
    return 0;
}
